  tasks: [
    {q:"Кнопка 'PLAY' на экране.", hint:"Rect + draw.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,200)); f=pygame.font.SysFont('Arial',28,bold=True); cl=pygame.time.Clock(); btn=pygame.Rect(80,80,140,50); run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.MOUSEBUTTONDOWN and btn.collidepoint(e.pos): print('PLAY')\n    s.fill((20,20,50)); pygame.draw.rect(s,(0,150,255),btn,border_radius=8)\n    t=f.render('PLAY',True,(255,255,255)); s.blit(t,t.get_rect(center=btn.center))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Меню → игра по клику.", hint:"state.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,200)); f=pygame.font.SysFont('Arial',24); cl=pygame.time.Clock(); state='menu'; btn=pygame.Rect(80,80,140,50); run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.MOUSEBUTTONDOWN and state=='menu' and btn.collidepoint(e.pos): state='game'\n    if state=='menu':\n        s.fill((10,10,40)); pygame.draw.rect(s,(0,200,100),btn); s.blit(f.render('PLAY',True,(255,255,255)),(btn.x+40,btn.y+15))\n    else:\n        s.fill((30,80,30)); s.blit(f.render('Идёт игра!',True,(255,255,255)),(80,90))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Пауза по Escape.", hint:"state='pause'.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,150)); f=pygame.font.SysFont('Arial',30); cl=pygame.time.Clock(); paused=False; x=0; run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.KEYDOWN and e.key==pygame.K_ESCAPE: paused=not paused\n    if not paused: x=(x+3)%300\n    s.fill((0,0,0)); pygame.draw.rect(s,(0,255,0),(x,60,30,30))\n    if paused: s.blit(f.render('PAUSE',True,(255,255,0)),(110,55))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Несколько кнопок меню.", hint:"Список Rect.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,250)); f=pygame.font.SysFont('Arial',22); cl=pygame.time.Clock()\nopts=['Играть','Настройки','Выход']\nbtns=[pygame.Rect(80,40+i*60,140,40) for i in range(3)]; run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.MOUSEBUTTONDOWN:\n            for i,r in enumerate(btns):\n                if r.collidepoint(e.pos): print(opts[i])\n    s.fill((20,20,50))\n    for i,r in enumerate(btns):\n        pygame.draw.rect(s,(0,150,255),r,border_radius=6); s.blit(f.render(opts[i],True,(255,255,255)),(r.x+15,r.y+10))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Подсветка кнопки при наведении.", hint:"Hover-цвет.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,150)); cl=pygame.time.Clock(); btn=pygame.Rect(100,50,100,50); run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n    hov=btn.collidepoint(pygame.mouse.get_pos())\n    s.fill((20,20,40)); pygame.draw.rect(s,(255,200,0) if hov else (200,150,0),btn)\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Экран Game Over с кнопкой 'Заново'.", hint:"state='over'.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,200)); f=pygame.font.SysFont('Arial',26); cl=pygame.time.Clock(); state='over'; btn=pygame.Rect(80,120,140,40); run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.MOUSEBUTTONDOWN and state=='over' and btn.collidepoint(e.pos): state='game'\n    s.fill((30,0,0))\n    if state=='over':\n        s.blit(f.render('GAME OVER',True,(255,40,40)),(70,40))\n        pygame.draw.rect(s,(0,200,0),btn); s.blit(f.render('Заново',True,(255,255,255)),(btn.x+25,btn.y+8))\n    else: s.blit(f.render('Игра!',True,(0,255,0)),(110,80))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Меню с фоновой картинкой.", hint:"blit фона.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((400,300)); f=pygame.font.SysFont('Arial',32,bold=True); cl=pygame.time.Clock(); run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n    s.fill((50,0,80))\n    s.blit(f.render('My Game',True,(255,255,255)),(120,80))\n    pygame.draw.rect(s,(0,255,100),pygame.Rect(140,180,120,50),border_radius=8)\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Громкость через слайдер мышью.", hint:"Rect + drag.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,100)); cl=pygame.time.Clock(); vol=0.5; run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n    if pygame.mouse.get_pressed()[0]:\n        x=pygame.mouse.get_pos()[0]; vol=max(0,min(1,(x-20)/260))\n    s.fill((0,0,0)); pygame.draw.rect(s,(80,80,80),(20,40,260,10))\n    pygame.draw.rect(s,(0,255,0),(20,40,int(260*vol),10))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Выбор уровня (3 кнопки 1-2-3).", hint:"Цикл.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((400,150)); f=pygame.font.SysFont('Arial',32,bold=True); cl=pygame.time.Clock()\nbtns=[pygame.Rect(50+i*120,50,80,60) for i in range(3)]; run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.MOUSEBUTTONDOWN:\n            for i,r in enumerate(btns):\n                if r.collidepoint(e.pos): print('Уровень',i+1)\n    s.fill((20,20,40))\n    for i,r in enumerate(btns):\n        pygame.draw.rect(s,(0,150,200),r); s.blit(f.render(str(i+1),True,(255,255,0)),(r.x+30,r.y+12))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
    {q:"Закрытие игры по кнопке.", hint:"running=False.", solution:"import pygame\npygame.init()\ns=pygame.display.set_mode((300,100)); f=pygame.font.SysFont('Arial',24); cl=pygame.time.Clock(); btn=pygame.Rect(100,30,100,40); run=True\nwhile run:\n    for e in pygame.event.get():\n        if e.type==pygame.QUIT: run=False\n        if e.type==pygame.MOUSEBUTTONDOWN and btn.collidepoint(e.pos): run=False\n    s.fill((0,0,0)); pygame.draw.rect(s,(255,40,40),btn); s.blit(f.render('Quit',True,(255,255,255)),(btn.x+25,btn.y+8))\n    pygame.display.flip(); cl.tick(60)\npygame.quit()"},
  ],
